// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }

    function testFuzz_property(uint256 value, bool calleeReverts) public {
        vm.assume(value <= type(uint256).max);

        address callee;
        if (calleeReverts) {
            callee = address(new Reverter());
        } else {
            callee = address(new Acceptor());
        }

        address owner = c.Owner();
        vm.deal(owner, value);

        bool ok;
        vm.prank(owner);
        try c.Command{value: value}(callee, "") {
            ok = true;
        } catch {
            ok = false;
        }

        if (!calleeReverts) {
            assertTrue(ok);
        } else {
            assertTrue(true);
        }
    }
}

contract Reverter {
    fallback() external payable {
        revert("bad");
    }
}

contract Acceptor {
    fallback() external payable {
    }
}
